U8 *bench_src="// COM1 interrupt-driven telemetry
#define BENCH_RING 16384
U8 bench_ring[BENCH_RING];
U64 bench_head=0,bench_tail=0,bench_drops=0;
Bool bench_on=FALSE;
CTask *bench_task=NULL;
U8 *bench_old_entry;
U8 bench_old_pic,bench_old_lcr,bench_old_ier,bench_old_mcr;
U8 bench_old_dll,bench_old_dlm,bench_old_scr;
interrupt U0 BenchRxIRQ()
{
 U8 b; U64 n;
 while (InU8(0x3FD)&1) {
  b=InU8(0x3F8);
  n=(bench_head+1)&(BENCH_RING-1);
  if (n!=bench_tail) {bench_ring[bench_head]=b;bench_head=n;}
  else bench_drops++;
 }
 InU8(0x3FA);
 OutU8(0x20,0x20);
}
U0 BenchTx(U8 b)
{
 while (!(InU8(0x3FD)&0x20)) Yield;
 OutU8(0x3F8,b);
}
U32 BenchCRC(U8 *p,I64 n)
{
 U32 c=0xFFFFFFFF; I64 i,j;
 for (i=0;i<n;i++) {
  c^=p[i];
  for (j=0;j<8;j++) {
   if (c&1) c=(c>>1)^0xEDB88320; else c>>=1;
  }
 }
 return c^0xFFFFFFFF;
}
U0 BenchReply(U8 seq,U8 *p,I64 n)
{
 U32 c=BenchCRC(p,n); U8 b,sum=seq; I64 i;
 BenchTx(0x5A); BenchTx(seq);
 for (i=0;i<4;i++) {b=(c>>(8*i))&255;sum+=b;BenchTx(b);}
 BenchTx(sum);
}
U0 BenchWorker(U8 *unused)
{
 U8 frame[128],sum; I64 used=0,i,n,drop;
 while (bench_on) {
  if (bench_tail==bench_head) {Sleep(1);continue;}
  frame[used++]=bench_ring[bench_tail];
  bench_tail=(bench_tail+1)&(BENCH_RING-1);
  while (used) {
   drop=0;
   if (frame[0]!=0xA5) drop=1;
   else if (used<3) break;
   else {
    n=frame[2];
    if (n<1 || n>64) drop=1;
    else if (used<n+4) break;
    else {
     sum=frame[1]+frame[2];
     for (i=0;i<n;i++) sum+=frame[3+i];
     if (sum==frame[n+3]) {BenchReply(frame[1],frame+3,n);drop=n+4;}
     else drop=1;
    }
   }
   used-=drop;
   for (i=0;i<used;i++) frame[i]=frame[i+drop];
  }
 }
}
U0 BenchStart()
{
 if (bench_on) return;
 bench_old_pic=InU8(0x21)&0x10;
 OutU8(0x21,InU8(0x21)|0x10);
 bench_old_entry=IntEntryGet(0x24);
 bench_old_lcr=InU8(0x3FB);
 bench_old_mcr=InU8(0x3FC);
 bench_old_scr=InU8(0x3FF);
 OutU8(0x3FB,bench_old_lcr&0x7F);
 bench_old_ier=InU8(0x3F9); OutU8(0x3F9,0);
 OutU8(0x3FB,0x80);
 bench_old_dll=InU8(0x3F8);bench_old_dlm=InU8(0x3F9);
 OutU8(0x3F8,1);OutU8(0x3F9,0);
 OutU8(0x3FB,3);
 OutU8(0x3FA,0x07);
 OutU8(0x3FC,0x0B);
 bench_head=0;bench_tail=0;bench_drops=0;bench_on=TRUE;
 IntEntrySet(0x24,&BenchRxIRQ);
 bench_task=Spawn(&BenchWorker,NULL,"COM1 telemetry");
 OutU8(0x3F9,1);
 OutU8(0x21,InU8(0x21)&~0x10);
}
U0 BenchStop()
{
 if (!bench_on) return;
 OutU8(0x21,InU8(0x21)|0x10);
 OutU8(0x3FB,3);OutU8(0x3F9,0);
 bench_on=FALSE;
 if (bench_task) {Kill(bench_task);bench_task=NULL;}
 IntEntrySet(0x24,bench_old_entry);
 OutU8(0x3FA,0);
 OutU8(0x3FB,0x80);
 OutU8(0x3F8,bench_old_dll);OutU8(0x3F9,bench_old_dlm);
 OutU8(0x3FB,bench_old_lcr&0x7F);
 OutU8(0x3F9,bench_old_ier);
 OutU8(0x3FC,bench_old_mcr);OutU8(0x3FF,bench_old_scr);
 OutU8(0x3FB,bench_old_lcr);
 OutU8(0x21,(InU8(0x21)&~0x10)|bench_old_pic);
}
";
FileWrite("B:/Bench/Telemetry.HC",bench_src,StrLen(bench_src));
#include "B:/Bench/Telemetry.HC";

